# Achilles + Data Quality Dashboard for the CDM built by omop-agent.
#
# Generated by omop-agent from omop_agent/quality/r/run_achilles_dqd.R; edits are overwritten on
# the next run. Needs the R packages DatabaseConnector, Achilles and DataQualityDashboard.
#
# The database password is never written to this file: it is read from the environment variable
# OMOP_AGENT_DB_PASSWORD, which omop-agent sets when it runs the script. To run it by hand:
#
#   OMOP_AGENT_DB_PASSWORD=... Rscript run_achilles_dqd.R
#
# The PostgreSQL JDBC driver is taken from DATABASECONNECTOR_JAR_FOLDER; when that is not set it is
# downloaded into <output folder>/jdbc on first use.

library(DatabaseConnector)

# R's SIGPIPE handler raises an R error. With TLS (pgJDBC's default sslmode=prefer) closing a
# connection can write to a socket the server has already closed, so that error is raised inside
# rJava and aborts DatabaseConnector::disconnect() ("ignoring SIGPIPE signal") or crashes the JVM
# later. Achilles and DQD connect and disconnect many times, so ignore SIGPIPE, as the JVM does.
invisible(rJava::.jinit())
invisible(rJava::J("sun.misc.Signal")$handle(
  rJava::.jnew("sun.misc.Signal", "PIPE"), rJava::J("sun.misc.SignalHandler")$SIG_IGN
))

# ---- settings (filled in by omop-agent) -------------------------------------------------------
server          <- {{server}}            # "host/database"
port            <- {{port}}
user            <- {{user}}
cdmSchema       <- {{cdm_schema}}
vocabSchema     <- {{vocab_schema}}
resultsSchema   <- {{results_schema}}
cdmSourceName   <- {{cdm_source_name}}
outputFolder    <- {{output_folder}}
resultsFile     <- {{results_file}}      # DQD JSON, read back by omop-agent
smallCellCount  <- {{small_cell_count}}  # Achilles suppresses counts below this
runAchilles     <- {{run_achilles}}

# ---- connection -------------------------------------------------------------------------------
# DatabaseConnector needs exactly one file named postgresql-<version>.jar in the folder. The
# omop-agent R image provides one (DATABASECONNECTOR_JAR_FOLDER=/opt/jdbc); elsewhere it is
# downloaded once into <output folder>/jdbc, which needs internet access.
driverFolder <- Sys.getenv("DATABASECONNECTOR_JAR_FOLDER")
if (driverFolder == "") {
  driverFolder <- file.path(outputFolder, "jdbc")
  dir.create(driverFolder, recursive = TRUE, showWarnings = FALSE)
  if (length(list.files(driverFolder, pattern = "^postgresql-.*\\.jar$")) == 0) {
    DatabaseConnector::downloadJdbcDrivers("postgresql", pathToDriver = driverFolder)
  }
}
if (length(list.files(driverFolder, pattern = "^postgresql-.*\\.jar$")) != 1) {
  stop(paste0(
    "need exactly one PostgreSQL JDBC driver named postgresql-<version>.jar in ", driverFolder,
    " (set DATABASECONNECTOR_JAR_FOLDER to a folder that holds one)"
  ))
}

connectionDetails <- DatabaseConnector::createConnectionDetails(
  dbms = "postgresql",
  server = server,
  port = port,
  user = user,
  password = Sys.getenv("OMOP_AGENT_DB_PASSWORD"),
  pathToDriver = driverFolder
)

dir.create(outputFolder, recursive = TRUE, showWarnings = FALSE)

# Achilles and DQD write their tables to the results schema; make sure it exists.
connection <- DatabaseConnector::connect(connectionDetails)
DatabaseConnector::executeSql(connection, paste0("CREATE SCHEMA IF NOT EXISTS ", resultsSchema, ";"))
DatabaseConnector::disconnect(connection)

# ---- Achilles: database characterization (feeds ATLAS "Data Sources") -------------------------
if (runAchilles) {
  Achilles::achilles(
    connectionDetails = connectionDetails,
    cdmDatabaseSchema = cdmSchema,
    resultsDatabaseSchema = resultsSchema,
    vocabDatabaseSchema = vocabSchema,
    sourceName = cdmSourceName,
    cdmVersion = "5.4",
    smallCellCount = smallCellCount,
    outputFolder = file.path(outputFolder, "achilles")
  )
}

# ---- Data Quality Dashboard -------------------------------------------------------------------
# Results are written as JSON to file.path(outputFolder, resultsFile); omop-agent parses the
# "CheckResults" list from it. Vocabulary tables are excluded: they come from Athena as-is.
DataQualityDashboard::executeDqChecks(
  connectionDetails = connectionDetails,
  cdmDatabaseSchema = cdmSchema,
  resultsDatabaseSchema = resultsSchema,
  vocabDatabaseSchema = vocabSchema,
  # omop-agent creates COHORT and COHORT_DEFINITION in the CDM schema; DQD looks for them in
  # cohortDatabaseSchema (default: the results schema).
  cohortDatabaseSchema = cdmSchema,
  cdmSourceName = cdmSourceName,
  cdmVersion = "5.4",
  outputFolder = outputFolder,
  outputFile = resultsFile,
  writeToTable = FALSE,
  tablesToExclude = c(
    "CONCEPT", "VOCABULARY", "CONCEPT_ANCESTOR", "CONCEPT_RELATIONSHIP",
    "CONCEPT_CLASS", "CONCEPT_SYNONYM", "RELATIONSHIP", "DOMAIN"
  )
)

# To browse the results: DataQualityDashboard::viewDqDashboard(file.path(outputFolder, resultsFile))
